// Code generated by mygo; DO NOT EDIT.

package transpiler

import (
	"bytes"
	"errors"
	"fmt"
	"io"

	"github.com/aisk/mygo/ast"
	"github.com/aisk/mygo/astutil"
	"github.com/aisk/mygo/containers"
	"github.com/aisk/mygo/format"
	"github.com/aisk/mygo/parser"
	"github.com/aisk/mygo/token"
)

const generatedCodeComment = "// Code generated by mygo; DO NOT EDIT."

// transpiler holds the state of a single Transpile call, so a failed run
// cannot leak state into the next one.
type transpiler struct {
	fset  *token.FileSet
	file  *ast.File
	funcs containers.Stack[*ast.FuncType]
	// names holds every identifier in the source plus every name generated
	// so far; generated temporaries never reuse one of them.
	names map[string]bool
}

func writeGeneratedCodeComment(output io.Writer) error {
	_, err := io.WriteString(output, generatedCodeComment+"\n\n")
	return err
}

func posAfterTrailingComments(fset *token.FileSet, comments []*ast.CommentGroup, node ast.Node) token.Pos {
	pos := node.End()
	line := fset.Position(node.Pos()).Line
	found := false
	for _, comment := range comments {
		commentPos := fset.Position(comment.Pos())
		if commentPos.Line == line && comment.Pos() >= pos {
			pos = comment.End() + 1
			found = true
		}
	}
	if !found {
		for _, comment := range comments {
			if comment.Pos() > pos {
				return pos
			}
		}
		return token.NoPos
	}
	return pos
}

func genErrNotNilCond(pos token.Pos) ast.Expr {
	return &ast.BinaryExpr{
		X:     &ast.Ident{NamePos: pos, Name: "err"},
		OpPos: pos,
		Op:    token.NEQ,
		Y:     &ast.Ident{NamePos: pos, Name: "nil"},
	}
}

func (t *transpiler) preVisit(c *astutil.Cursor) bool {
	// Push FuncType to a stack for find the enclosing one.
	n := c.Node()
	switch x := n.(type) {
	case *ast.FuncDecl:
		t.funcs.Push(x.Type)
	case *ast.FuncLit:
		t.funcs.Push(x.Type)
	}
	return true
}

func (t *transpiler) getEnclosingFuncType() (*ast.FuncType, error) {
	ftype, exist := t.funcs.Peek()
	if !exist {
		return nil, errors.New("no enclosing function")
	}
	return ftype, nil
}

// newName returns an identifier that appears nowhere in the source and has
// not been generated before.
func (t *transpiler) newName(base string) string {
	name := base
	for i := 1; t.names[name]; i++ {
		name = fmt.Sprintf("%s%d", base, i)
	}
	t.names[name] = true
	return name
}

func genEmptyValueExpr(fset *token.FileSet, typ ast.Expr) (ast.Expr, error) {
	switch t := typ.(type) {
	case *ast.Ident:
		switch t.Name {
		case "error", "any":
			return &ast.Ident{Name: "nil"}, nil
		case "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "float32", "float64", "uintptr", "rune", "byte":
			return &ast.BasicLit{Kind: token.INT, Value: "0"}, nil
		case "bool":
			return &ast.Ident{Name: "false"}, nil
		case "string":
			return &ast.BasicLit{Kind: token.STRING, Value: `""`}, nil
		}
	case *ast.StarExpr, *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.InterfaceType:
		return &ast.Ident{Name: "nil"}, nil
	case *ast.ArrayType:
		if t.Len == nil { // a slice, not a fixed-size array
			return &ast.Ident{Name: "nil"}, nil
		}
	case *ast.ParenExpr:
		return genEmptyValueExpr(fset, t.X)
	}
	// *new(T) is the zero value of any type T. Render the type to a plain
	// string so the generated expression carries no position info from the
	// function signature, which would confuse the printer's line tracking.
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, typ); err != nil {
		return *new(ast.Expr), err
	}
	return &ast.StarExpr{
		X: &ast.CallExpr{
			Fun:  &ast.Ident{Name: "new"},
			Args: []ast.Expr{&ast.Ident{Name: buf.String()}},
		},
	}, nil
}

func genResults(fset *token.FileSet, results *ast.FieldList) ([]ast.Expr, error) {
	if results == nil || len(results.List) == 0 {
		return nil, fmt.Errorf("try expression used in function that does not return an error")
	}

	fields := results.List
	var resultsExpr []ast.Expr

	// Check if the last parameter is an error type
	lastField := fields[len(fields)-1]
	if ident, ok := lastField.Type.(*ast.Ident); !ok || ident.Name != "error" {
		return nil, fmt.Errorf("try expression used in function that does not return an error")
	}

	// Generate empty values for all parameters. A field may declare several
	// names (e.g. `a, b int`) and needs one value per name.
	for _, field := range fields {
		expr, err := genEmptyValueExpr(fset, field.Type)
		if err != nil {
			return nil, err
		}
		count := len(field.Names)
		if count == 0 {
			count = 1
		}
		for i := 0; i < count; i++ {
			resultsExpr = append(resultsExpr, expr)
		}
	}

	// Replace the last parameter (which is error) with "err"
	resultsExpr[len(resultsExpr)-1] = &ast.Ident{Name: "err"}

	return resultsExpr, nil
}

func genErrorHandlerBlock(fset *token.FileSet, handler *ast.BlockStmt, results *ast.FieldList, pos token.Pos) (*ast.BlockStmt, error) {
	if handler != nil {
		return handler, nil
	}

	resultsExpr, err := genResults(fset, results)
	if err != nil {
		return nil, err
	}
	if pos.IsValid() {
		resultsExpr[len(resultsExpr)-1] = &ast.Ident{NamePos: pos, Name: "err"}
	}
	block := &ast.BlockStmt{
		List: []ast.Stmt{
			&ast.ReturnStmt{
				Results: resultsExpr,
			},
		},
	}
	if pos.IsValid() {
		block.Lbrace = pos
		block.List[0].(*ast.ReturnStmt).Return = pos
		block.Rbrace = pos
	}
	return block, nil
}

// genErrCheck generates `if err != nil { <handler> }` for a try expression.
func (t *transpiler) genErrCheck(tryExpr *ast.TryExpr, pos token.Pos) (*ast.IfStmt, error) {
	enclosingFunc, err := t.getEnclosingFuncType()
	if err != nil {
		return nil, err
	}
	handler, err := genErrorHandlerBlock(t.fset, tryExpr.Handler, enclosingFunc.Results, pos)
	if err != nil {
		return nil, err
	}
	return &ast.IfStmt{
		If:   pos,
		Cond: genErrNotNilCond(pos),
		Body: handler,
	}, nil
}

func getReaderFileName(reader io.Reader) string {
	filename := "*unknown*"
	if f, ok := reader.(interface{ Name() string }); ok {
		filename = f.Name()
	}
	return filename
}

func Transpile(input io.Reader, output io.Writer) error {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, getReaderFileName(input), input, parser.ParseComments)
	if err != nil {
		return err
	}

	// ast.Print(fset, file)

	t := &transpiler{fset: fset, file: file, names: map[string]bool{}}
	ast.Inspect(file, func(n ast.Node) bool {
		if ident, ok := n.(*ast.Ident); ok {
			t.names[ident.Name] = true
		}
		return true
	})

	var transpileError error
	astutil.Apply(file, t.preVisit, func(c *astutil.Cursor) bool {
		if err := t.postVisit(c); err != nil {
			transpileError = fmt.Errorf("%s: %v", fset.Position(c.Node().Pos()), err)
			return false
		}
		return true
	})
	if transpileError != nil {
		return transpileError
	}

	// Any try expression left in the tree sits in a position the transpiler
	// does not handle; report it instead of emitting invalid Go.
	if leftover := findTryExpr(file); leftover != nil {
		return fmt.Errorf("%s: ? is not supported in this position", fset.Position(leftover.Question))
	}

	if err := writeGeneratedCodeComment(output); err != nil {
		return err
	}
	if err := format.Node(output, fset, file); err != nil {
		return err
	}
	return nil
}

func (t *transpiler) postVisit(c *astutil.Cursor) error {
	switch x := c.Node().(type) {
	case *ast.FuncDecl, *ast.FuncLit:
		// Pop the FuncType stack.
		t.funcs.Pop()
	case *ast.AssignStmt:
		// Handle x := f()?, x = f()?, x += f()?
		if topLevelTry(x) == nil {
			break
		}
		if _, ok := c.Parent().(*ast.IfStmt); ok && c.Name() == "Init" {
			// Lowered together with the enclosing if statement.
			break
		}
		stmts, err := t.lowerAssign(x)
		if err != nil {
			return err
		}
		return replaceStmt(c, stmts)
	case *ast.DeclStmt:
		// Handle var x = f()? and var x T = f()?, grouped or not.
		gen, ok := x.Decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.VAR {
			break
		}
		stmts, err := t.lowerVarDecl(gen)
		if err != nil {
			return err
		}
		if stmts != nil {
			return replaceStmt(c, stmts)
		}
	case *ast.ExprStmt:
		// Handle f()?
		tryX, ok := x.X.(*ast.TryExpr)
		if !ok {
			break
		}
		ifPos := posAfterTrailingComments(t.fset, t.file.Comments, x)
		check, err := t.genErrCheck(tryX, ifPos)
		if err != nil {
			return err
		}
		check.Init = &ast.AssignStmt{
			Lhs: []ast.Expr{
				&ast.Ident{Name: "err"},
			},
			Tok: token.DEFINE,
			Rhs: []ast.Expr{
				tryX.X,
			},
		}
		return replaceStmt(c, []ast.Stmt{check})
	case *ast.IfStmt:
		// Handle try expressions in the condition (if f()? > 0 { ... }) and
		// in the init statement (if x := f()?; x > 0 { ... }).
		newStmt, err := t.lowerIf(x)
		if err != nil {
			return err
		}
		if newStmt != nil {
			c.Replace(newStmt)
		}
	}
	return nil
}

// replaceStmt replaces the statement at the cursor with stmts.
func replaceStmt(c *astutil.Cursor, stmts []ast.Stmt) error {
	if c.Index() < 0 {
		// Only a labeled statement can hold a single replacement statement;
		// other positions (for/switch init and post) need a simple statement.
		if _, ok := c.Parent().(*ast.LabeledStmt); ok && len(stmts) == 1 {
			c.Replace(stmts[0])
			return nil
		}
		return errors.New("? is not supported in this statement position")
	}
	for _, stmt := range stmts[:len(stmts)-1] {
		c.InsertBefore(stmt)
	}
	c.Replace(stmts[len(stmts)-1])
	return nil
}

// topLevelTry returns the try expression of `lhs op f()?`, or nil.
func topLevelTry(stmt ast.Stmt) *ast.TryExpr {
	assign, ok := stmt.(*ast.AssignStmt)
	if !ok || len(assign.Rhs) != 1 {
		return nil
	}
	tryExpr, _ := assign.Rhs[0].(*ast.TryExpr)
	return tryExpr
}

func isBlank(expr ast.Expr) bool {
	ident, ok := expr.(*ast.Ident)
	return ok && ident.Name == "_"
}

func allBlank(exprs []ast.Expr) bool {
	for _, expr := range exprs {
		if !isBlank(expr) {
			return false
		}
	}
	return true
}

// lowerAssign lowers an assignment whose right-hand side is f()?.
func (t *transpiler) lowerAssign(x *ast.AssignStmt) ([]ast.Stmt, error) {
	tryExpr := topLevelTry(x)
	ifPos := posAfterTrailingComments(t.fset, t.file.Comments, x)
	check, err := t.genErrCheck(tryExpr, ifPos)
	if err != nil {
		return nil, err
	}

	if x.Tok == token.DEFINE {
		x.Rhs[0] = tryExpr.X
		x.Lhs = append(x.Lhs, &ast.Ident{Name: "err"})
		return []ast.Stmt{x, check}, nil
	}

	if x.Tok == token.ASSIGN && allBlank(x.Lhs) {
		// _ = f()?  =>  if _, err := f(); err != nil { ... }
		x.Rhs[0] = tryExpr.X
		x.Lhs = append(x.Lhs, &ast.Ident{Name: "err"})
		x.Tok = token.DEFINE
		check.Init = x
		return []ast.Stmt{check}, nil
	}

	// `err` may not be declared and the left-hand side must not be
	// redeclared, so receive the values into fresh temporaries and assign
	// them only once the error check has passed. Calls on the left-hand side
	// are hoisted first to keep Go's left-to-right evaluation order.
	var stmts []ast.Stmt
	var lhs []ast.Expr
	var recvLhs []ast.Expr
	var temps []ast.Expr
	for _, expr := range x.Lhs {
		if isBlank(expr) {
			recvLhs = append(recvLhs, expr)
			continue
		}
		name := t.newName("result")
		recvLhs = append(recvLhs, &ast.Ident{Name: name})
		lhs = append(lhs, t.spillAddressable(expr, &stmts))
		temps = append(temps, &ast.Ident{Name: name})
	}
	recv := &ast.AssignStmt{
		Lhs:    append(recvLhs, &ast.Ident{Name: "err"}),
		TokPos: x.TokPos,
		Tok:    token.DEFINE,
		Rhs:    []ast.Expr{tryExpr.X},
	}
	stmts = append(stmts, recv, check, &ast.AssignStmt{Lhs: lhs, Tok: x.Tok, Rhs: temps})
	return stmts, nil
}

// lowerVarDecl lowers a local var declaration containing f()? specs. It
// returns nil if the declaration contains no top-level try expression.
func (t *transpiler) lowerVarDecl(gen *ast.GenDecl) ([]ast.Stmt, error) {
	hasTry := false
	for _, spec := range gen.Specs {
		if valueSpecTry(spec) != nil {
			hasTry = true
		}
	}
	if !hasTry {
		return nil, nil
	}

	var stmts []ast.Stmt
	var pending []ast.Spec
	flush := func() {
		if len(pending) > 0 {
			stmts = append(stmts, &ast.DeclStmt{Decl: &ast.GenDecl{Tok: token.VAR, Specs: pending}})
			pending = nil
		}
	}
	for _, spec := range gen.Specs {
		tryExpr := valueSpecTry(spec)
		if tryExpr == nil {
			pending = append(pending, spec)
			continue
		}
		flush()
		vspec := spec.(*ast.ValueSpec)
		ifPos := posAfterTrailingComments(t.fset, t.file.Comments, vspec)
		check, err := t.genErrCheck(tryExpr, ifPos)
		if err != nil {
			return nil, err
		}

		var names []ast.Expr
		for _, name := range vspec.Names {
			names = append(names, name)
		}

		if allBlank(names) {
			// var _ = f()?  =>  if _, err := f(); err != nil { ... }
			check.Init = &ast.AssignStmt{
				Lhs: append(names, &ast.Ident{Name: "err"}),
				Tok: token.DEFINE,
				Rhs: []ast.Expr{tryExpr.X},
			}
			stmts = append(stmts, check)
			continue
		}

		if vspec.Type == nil {
			// var x = f()?  =>  x, err := f()
			stmts = append(stmts, &ast.AssignStmt{
				Lhs: append(names, &ast.Ident{Name: "err"}),
				Tok: token.DEFINE,
				Rhs: []ast.Expr{tryExpr.X},
			}, check)
			continue
		}

		// var x T = f()?  =>  receive into temporaries, then declare x with
		// its type so the declared type is kept (e.g. an interface).
		var recvLhs []ast.Expr
		var temps []ast.Expr
		for _, name := range names {
			if isBlank(name) {
				recvLhs = append(recvLhs, name)
				continue
			}
			temp := t.newName("result")
			recvLhs = append(recvLhs, &ast.Ident{Name: temp})
			temps = append(temps, &ast.Ident{Name: temp})
		}
		var declNames []*ast.Ident
		for _, name := range vspec.Names {
			if !isBlank(name) {
				declNames = append(declNames, name)
			}
		}
		stmts = append(stmts, &ast.AssignStmt{
			Lhs: append(recvLhs, &ast.Ident{Name: "err"}),
			Tok: token.DEFINE,
			Rhs: []ast.Expr{tryExpr.X},
		}, check, &ast.DeclStmt{Decl: &ast.GenDecl{
			Tok:   token.VAR,
			Specs: []ast.Spec{&ast.ValueSpec{Names: declNames, Type: vspec.Type, Values: temps}},
		}})
	}
	flush()
	return stmts, nil
}

func valueSpecTry(spec ast.Spec) *ast.TryExpr {
	vspec, ok := spec.(*ast.ValueSpec)
	if !ok || len(vspec.Values) != 1 {
		return nil
	}
	tryExpr, _ := vspec.Values[0].(*ast.TryExpr)
	return tryExpr
}

// lowerIf lowers an if statement with try expressions in its init statement
// or condition. It returns nil if there is nothing to lower.
func (t *transpiler) lowerIf(x *ast.IfStmt) (ast.Stmt, error) {
	initTry := x.Init != nil && topLevelTry(x.Init) != nil
	if !initTry && !containsTryExpr(x.Cond) {
		return nil, nil
	}
	ifPos := posAfterTrailingComments(t.fset, t.file.Comments, x)

	var stmts []ast.Stmt
	if initTry {
		initStmts, err := t.lowerAssign(x.Init.(*ast.AssignStmt))
		if err != nil {
			return *new(ast.Stmt), err
		}
		stmts = append(stmts, initStmts...)
	} else if x.Init != nil {
		stmts = append(stmts, x.Init)
	}
	condStmts, cond, err := t.lowerExpr(x.Cond, ifPos)
	if err != nil {
		return *new(ast.Stmt), err
	}

	if x.Init == nil && isTryReceive(condStmts) {
		// if f()? > 0 { ... }  =>
		// if result, err := f(); err != nil { ... } else if result > 0 { ... }
		check := condStmts[1].(*ast.IfStmt)
		check.Init = condStmts[0]
		check.Else = &ast.IfStmt{
			Cond: cond,
			Body: x.Body,
			Else: x.Else,
		}
		return check, nil
	}

	// The general form wraps everything in a block, so the init statement,
	// temporaries and err stay scoped to the if statement.
	x.Init = nil
	x.Cond = cond
	stmts = append(stmts, condStmts...)
	stmts = append(stmts, x)
	return &ast.BlockStmt{Lbrace: x.If, List: stmts, Rbrace: x.End()}, nil
}

// isTryReceive reports whether stmts is exactly `v, err := f()` followed by
// its error check, as produced by lowerExpr for a single try expression.
func isTryReceive(stmts []ast.Stmt) bool {
	if len(stmts) != 2 {
		return false
	}
	recv, ok := stmts[0].(*ast.AssignStmt)
	if !ok || recv.Tok != token.DEFINE || len(recv.Lhs) != 2 {
		return false
	}
	ident, ok := recv.Lhs[1].(*ast.Ident)
	return ok && ident.Name == "err"
}

// lowerExpr hoists the try expressions in expr into statements and returns
// them with the expression that remains. Go's evaluation order is kept:
// calls that precede a try expression are hoisted into temporaries too, and
// a try expression on the right of && or || only runs when Go would
// evaluate that operand.
func (t *transpiler) lowerExpr(expr ast.Expr, pos token.Pos) ([]ast.Stmt, ast.Expr, error) {
	if !containsTryExpr(expr) {
		return nil, expr, nil
	}
	switch v := expr.(type) {
	case *ast.TryExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		check, err := t.genErrCheck(v, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		name := t.newName("result")
		stmts = append(stmts, &ast.AssignStmt{
			Lhs: []ast.Expr{&ast.Ident{Name: name}, &ast.Ident{Name: "err"}},
			Tok: token.DEFINE,
			Rhs: []ast.Expr{x},
		}, check)
		return stmts, &ast.Ident{Name: name}, nil
	case *ast.BinaryExpr:
		if (v.Op == token.LAND || v.Op == token.LOR) && containsTryExpr(v.Y) {
			// a && f()?  =>  cond := a; if cond { ...; cond = f() result }
			stmts, x, err := t.lowerExpr(v.X, pos)
			if err != nil {
				return nil, *new(ast.Expr), err
			}
			yStmts, y, err := t.lowerExpr(v.Y, pos)
			if err != nil {
				return nil, *new(ast.Expr), err
			}
			name := t.newName("cond")
			var test ast.Expr = &ast.Ident{Name: name}
			if v.Op == token.LOR {
				test = &ast.UnaryExpr{Op: token.NOT, X: &ast.Ident{Name: name}}
			}
			yStmts = append(yStmts, &ast.AssignStmt{
				Lhs: []ast.Expr{&ast.Ident{Name: name}},
				Tok: token.ASSIGN,
				Rhs: []ast.Expr{y},
			})
			stmts = append(stmts, &ast.AssignStmt{
				Lhs: []ast.Expr{&ast.Ident{Name: name}},
				Tok: token.DEFINE,
				Rhs: []ast.Expr{x},
			}, &ast.IfStmt{
				Cond: test,
				Body: &ast.BlockStmt{List: yStmts},
			})
			return stmts, &ast.Ident{Name: name}, nil
		}
		stmts, ops, err := t.lowerOperands([]ast.Expr{v.X, v.Y}, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X, v.Y = ops[0], ops[1]
		return stmts, v, nil
	case *ast.ParenExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X = x
		return stmts, v, nil
	case *ast.UnaryExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X = x
		return stmts, v, nil
	case *ast.StarExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X = x
		return stmts, v, nil
	case *ast.SelectorExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X = x
		return stmts, v, nil
	case *ast.TypeAssertExpr:
		stmts, x, err := t.lowerExpr(v.X, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X = x
		return stmts, v, nil
	case *ast.CallExpr:
		operands := append([]ast.Expr{v.Fun}, v.Args...)
		stmts, ops, err := t.lowerOperands(operands, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.Fun, v.Args = ops[0], ops[1:]
		return stmts, v, nil
	case *ast.IndexExpr:
		stmts, ops, err := t.lowerOperands([]ast.Expr{v.X, v.Index}, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X, v.Index = ops[0], ops[1]
		return stmts, v, nil
	case *ast.SliceExpr:
		stmts, ops, err := t.lowerOperands([]ast.Expr{v.X, v.Low, v.High, v.Max}, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.X, v.Low, v.High, v.Max = ops[0], ops[1], ops[2], ops[3]
		return stmts, v, nil
	case *ast.CompositeLit:
		stmts, ops, err := t.lowerOperands(v.Elts, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.Elts = ops
		return stmts, v, nil
	case *ast.KeyValueExpr:
		stmts, ops, err := t.lowerOperands([]ast.Expr{v.Key, v.Value}, pos)
		if err != nil {
			return nil, *new(ast.Expr), err
		}
		v.Key, v.Value = ops[0], ops[1]
		return stmts, v, nil
	}
	return nil, nil, errors.New("? is not supported in this expression")
}

// lowerOperands lowers operands evaluated left to right. Operands before the
// last one containing a try expression are hoisted into temporaries when
// they contain calls, so those calls still run first.
func (t *transpiler) lowerOperands(operands []ast.Expr, pos token.Pos) ([]ast.Stmt, []ast.Expr, error) {
	last := -1
	for i, operand := range operands {
		if operand != nil && containsTryExpr(operand) {
			last = i
		}
	}
	var stmts []ast.Stmt
	result := make([]ast.Expr, len(operands))
	for i, operand := range operands {
		if operand == nil || i > last {
			result[i] = operand
			continue
		}
		operandStmts, x, err := t.lowerExpr(operand, pos)
		if err != nil {
			return nil, nil, err
		}
		stmts = append(stmts, operandStmts...)
		if i < last {
			x = t.spill(x, &stmts)
		}
		result[i] = x
	}
	return stmts, result, nil
}

// spill moves expr into a temporary if evaluating it calls a function or
// receives from a channel.
func (t *transpiler) spill(expr ast.Expr, stmts *[]ast.Stmt) ast.Expr {
	if !containsCall(expr) {
		return expr
	}
	name := t.newName("tmp")
	*stmts = append(*stmts, &ast.AssignStmt{
		Lhs: []ast.Expr{&ast.Ident{Name: name}},
		Tok: token.DEFINE,
		Rhs: []ast.Expr{expr},
	})
	return &ast.Ident{Name: name}
}

// spillAddressable hoists the calls inside an assignment target while
// keeping the target itself assignable.
func (t *transpiler) spillAddressable(expr ast.Expr, stmts *[]ast.Stmt) ast.Expr {
	switch v := expr.(type) {
	case *ast.Ident:
		return v
	case *ast.ParenExpr:
		v.X = t.spillAddressable(v.X, stmts)
		return v
	case *ast.SelectorExpr:
		v.X = t.spillAddressable(v.X, stmts)
		return v
	case *ast.IndexExpr:
		v.X = t.spillAddressable(v.X, stmts)
		v.Index = t.spill(v.Index, stmts)
		return v
	case *ast.StarExpr:
		v.X = t.spill(v.X, stmts)
		return v
	}
	return t.spill(expr, stmts)
}

// containsCall reports whether evaluating expr may call a function or
// receive from a channel. Function literal bodies are not evaluated.
func containsCall(expr ast.Expr) bool {
	found := false
	ast.Inspect(expr, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncLit:
			return false
		case *ast.CallExpr:
			found = true
		case *ast.UnaryExpr:
			if v.Op == token.ARROW {
				found = true
			}
		}
		return !found
	})
	return found
}

// containsTryExpr checks if an expression contains any TryExpr nodes
func containsTryExpr(expr ast.Expr) bool {
	if expr == nil {
		return false
	}
	return findTryExpr(expr) != nil
}

func findTryExpr(node ast.Node) *ast.TryExpr {
	var found *ast.TryExpr
	ast.Inspect(node, func(n ast.Node) bool {
		if found != nil {
			return false
		}
		if tryExpr, ok := n.(*ast.TryExpr); ok {
			found = tryExpr
			return false
		}
		return true
	})
	return found
}
